use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // Build a hash set from the smaller vector
    let (small, large) = if a.len() <= b.len() { (a, b) } else { (b, a) };
    let set: HashSet<_> = small.into_iter().collect();

    // Check if any element of the larger vector is in the set
    large.into_iter().any(|item| set.contains(&item))
}

